CREATE TABLE IF NOT EXISTS appointments (id TEXT PRIMARY KEY,folio TEXT UNIQUE NOT NULL,service_id TEXT NOT NULL,service_name TEXT NOT NULL,date TEXT NOT NULL,start_at TEXT UNIQUE NOT NULL,end_at TEXT NOT NULL,name TEXT NOT NULL,email TEXT NOT NULL,phone TEXT NOT NULL,age INTEGER,address TEXT,city TEXT,postal_code TEXT,height INTEGER,reason TEXT,status TEXT NOT NULL,payment_option TEXT,amount_due REAL,amount_paid REAL DEFAULT 0,payment_id TEXT,payment_status TEXT,hold_until TEXT,calendar_event_id TEXT,created_at TEXT NOT NULL,updated_at TEXT);CREATE INDEX IF NOT EXISTS idx_appointments_date ON appointments(date,status);CREATE TABLE IF NOT EXISTS form_submissions (id TEXT PRIMARY KEY,folio TEXT UNIQUE NOT NULL,type TEXT NOT NULL,name TEXT NOT NULL,email TEXT,phone TEXT,payload TEXT NOT NULL,created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS waitlist_requests (id TEXT PRIMARY KEY,folio TEXT UNIQUE NOT NULL,service_id TEXT NOT NULL,service_name TEXT NOT NULL,name TEXT NOT NULL,email TEXT NOT NULL,phone TEXT,preferred_date TEXT,status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL);CREATE INDEX IF NOT EXISTS idx_waitlist_service ON waitlist_requests(service_id,status,created_at);CREATE TABLE IF NOT EXISTS rate_limits (key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);CREATE TABLE IF NOT EXISTS site_events (id TEXT PRIMARY KEY,event TEXT NOT NULL,path TEXT NOT NULL,referrer TEXT,details TEXT,created_at TEXT NOT NULL);CREATE INDEX IF NOT EXISTS idx_site_events_created ON site_events(created_at,event);
CREATE TABLE IF NOT EXISTS recipes (id TEXT PRIMARY KEY,slug TEXT UNIQUE NOT NULL,title TEXT NOT NULL,summary TEXT NOT NULL,ingredients TEXT NOT NULL,steps TEXT NOT NULL,tags TEXT NOT NULL,image_url TEXT,status TEXT NOT NULL DEFAULT 'published',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);CREATE INDEX IF NOT EXISTS idx_recipes_status ON recipes(status,created_at);
